<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue'

import PageSurface from '../shared/components/PageSurface.vue'
import PageHeader from '../shared/components/PageHeader.vue'
import HelpTip from '../shared/components/HelpTip.vue'
import {toast} from '../shared/composables/toast.js'

import SuiteBindings from './SuiteBindings.vue'
import {visibilityOptions,suitePlan,validateSuiteBindings} from './collectionModel.js'
const props=defineProps({regressionContext:{type:Object,default:()=>({})},service:{type:String,required:true},cases:{type:Array,default:()=>[]}}),emit=defineEmits(['back'])
const bindingsOpen=ref([])
const suites=ref([]),search=ref(''),editing=ref(false),draft=ref({}),baseline=ref(''),saving=ref(false),loading=ref(false),toAdd=ref(null),nameInput=ref(null)
const dirty=computed(()=>editing.value&&JSON.stringify(draft.value)!==baseline.value),filtered=computed(()=>suites.value.filter(s=>s.name.toLowerCase().includes(search.value.toLowerCase()))),plan=computed(()=>suitePlan(draft.value,props.cases))
const selected=computed(()=>plan.value.selected.map((c,i)=>({...c,id:draft.value.case_ids[i],missing:!c})))
const available=computed(()=>props.cases.filter(c=>!draft.value.case_ids?.includes(c.id)&&(draft.value.visibility!=='team'||c.visibility==='team')).map(c=>({value:c.id,label:'TC-'+c.id+' · '+c.name})))
async function api(path,method='GET',value){const r=await fetch('api/api-testing/suites'+path+'?service='+encodeURIComponent(props.service),{method,...(value?{headers:{'Content-Type':'application/json'},body:JSON.stringify(value)}:{})});const b=await r.json();if(!r.ok||b.error)throw Error(b.error||'请求失败');return b}
let generation=0
async function load(){const app=props.service,token=++generation;if(!app){suites.value=[];return}loading.value=true;try{const value=await api('');if(token===generation&&app===props.service)suites.value=value}catch(e){if(token===generation)toast(e.message,'error')}finally{if(token===generation)loading.value=false}}
async function leave(){return !dirty.value||await confirmAction('测试集尚未保存，确认放弃改动？','离开测试集编辑')}
async function edit(s){if(!await leave())return;draft.value=s?JSON.parse(JSON.stringify(s)):{id:0,revision:0,name:'',visibility:'private',case_ids:[],can_edit:true,bindings:[]};draft.value.bindings||=[];baseline.value=JSON.stringify(draft.value);toAdd.value=null;editing.value=true}
async function back(){if(await leave())emit('back')}
async function cancel(){if(await leave())editing.value=false}
function move(i,d){const rows=draft.value.case_ids;[rows[i],rows[i+d]]=[rows[i+d],rows[i]]}
function add(id){if(id&&!draft.value.case_ids.includes(id)){draft.value.case_ids.push(id);toAdd.value=null}}
async function save(){if(saving.value)return;if(!draft.value.name.trim()){focusControl(nameInput.value);toast('请填写测试集名称','warning');return}if(!selected.value.length||plan.value.missing||plan.value.units>20||plan.value.steps>100){toast('选择有效用例，单次最多 20 个用例数据组合、100 个步骤','warning');return}try{validateSuiteBindings(draft.value.bindings||[],plan.value.selected)}catch(e){bindingsOpen.value=['bindings'];toast(e.message,'warning');return}saving.value=true;try{await api(draft.value.id?'/'+draft.value.id:'',draft.value.id?'PUT':'POST',draft.value);editing.value=false;await load();toast('测试集已保存','success')}catch(e){toast(e.message,'error')}finally{saving.value=false}}
async function remove(s){if(!await confirmAction('删除测试集会保留用例及历史报告。','删除测试集'))return;try{await api('/'+s.id,'DELETE');await load()}catch(e){toast(e.message,'error')}}
function execute(s){const hash='#/test-execution?'+new URLSearchParams({...props.regressionContext,service:props.service,suite:String(s.id)});if(window.parent!==window)window.parent.postMessage({type:'workspace.open',plugin:'api-center',hash},location.origin);else window.open(location.pathname+hash,'_blank','noopener')}
watch([dirty,saving],()=>{if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:dirty.value,busy:saving.value},location.origin)})
watch(()=>props.service,()=>{editing.value=false;load()},{immediate:true})
onBeforeUnmount(()=>generation++)

import OptionPicker from '../shared/components/OptionPicker.vue'

import {confirmAction} from '../shared/shadcnFeedback.js'

import {ref as _viewRef} from 'vue'
const _view1=_viewRef(1)

import {focusControl} from '../shared/focusControl.js'


import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Badge,Button,DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuTrigger,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldDescription,FieldError,FieldLabel,Input,Pagination,PaginationContent,PaginationNext,PaginationPrevious,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><main class="suites-page"><PageSurface><PageHeader :title="editing?(draft.id?'编辑测试集 · TS-'+draft.id:'新建测试集'):'测试集'" help="把可重复执行的业务用例按顺序组织成回归测试。执行时再选择环境和目标，复用环境认证；步骤变量在各用例和数据组间隔离，需要跨用例传值时显式配置变量关联。任一组合未通过即停止后续组合。"><template #actions><template v-if="editing"><Button @click="cancel" variant="outline" size="default" type="button" :disabled="(saving)">返回列表</Button><Button v-if="draft.can_edit" @click="save" variant="default" size="default" type="button" :disabled="(saving)"><Spinner v-if="saving"/>保存测试集</Button></template><template v-else><Badge variant="secondary">{{service}}</Badge><Button @click="back" variant="outline" size="default" type="button">返回测试用例</Button><Button @click="edit()" variant="default" size="default" type="button">新建测试集</Button></template></template></PageHeader><template v-if="!editing"><div class="filters"><InputGroup style="width:300px" class="min-w-0 "><InputGroupInput v-model="search" placeholder="搜索测试集名称" aria-label="搜索测试集"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="search" :disabled="false" size="icon-xs" aria-label="清空输入" @click="search='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><Button @click="load" variant="outline" size="default" type="button" :disabled="(loading)"><Spinner v-if="loading"/>刷新</Button></div><div class="min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:800}).y?({x:800}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:800}).x||({x:800}).minWidth||860)+'px'}"><TableHeader><TableRow><TableHead>测试集</TableHead><TableHead :style="{width:(130)+'px'}">编号 / 版本</TableHead><TableHead :style="{width:(150)+'px'}">用例 / 数据组合</TableHead><TableHead :style="{width:(110)+'px'}">共享范围</TableHead><TableHead :style="{width:(120)+'px'}">创建人</TableHead><TableHead :style="{width:(200)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (filtered||[]).slice((_view1-1)*(({pageSize:15}).pageSize||10),_view1*(({pageSize:15}).pageSize||10))" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="edit(record)" class="suite-name" variant="ghost" size="sm" type="button">{{record.name}}</Button></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">TS-{{record.id}} · v{{record.revision}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.case_ids.length}} 个 · {{suitePlan(record,cases).units}} 组</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Badge variant="secondary">{{record.visibility==='team'?'团队可用':'仅自己'}}</Badge></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["owner"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><div :size="0" class="flex flex-wrap items-center gap-2"><Button @click="execute(record)" variant="ghost" size="sm" type="button">执行</Button><Button v-if="record.can_edit" @click="edit(record)" variant="ghost" size="sm" type="button">编辑</Button><DropdownMenu v-if="record.can_edit"><DropdownMenuTrigger as-child><Button variant="ghost" size="sm" type="button">更多</Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem @select="remove(record)">删除测试集</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></template></div></TableCell></TableRow></template><TableRow v-if="!(filtered||[]).length"><TableCell :colspan="6"><Empty><EmptyHeader><EmptyDescription>{{"暂无测试集，选择已有用例组织一次回归测试"}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><div class="flex flex-wrap items-center justify-end gap-3 py-4"><span class="mr-auto text-sm text-muted-foreground">共 {{(filtered||[]).length}} 项</span><Pagination class="mx-0 w-auto" :page="_view1" :total="(filtered||[]).length" :items-per-page="({pageSize:15}).pageSize||10" @update:page="_view1=$event;"><PaginationContent><PaginationPrevious/><span class="px-2 text-sm">{{_view1}} / {{Math.max(1,Math.ceil(((filtered||[]).length)/(({pageSize:15}).pageSize||10)))}}</span><PaginationNext/></PaginationContent></Pagination></div></div></template><template v-else><fieldset :disabled="saving||!draft.can_edit" class="min-w-0 space-y-5" ><div class="basic"><Field><FieldLabel>测试集名称 <span class="text-destructive">*</span></FieldLabel><Input ref="nameInput" v-model="draft.name" placeholder="例如：订单核心流程回归" aria-label="测试集名称" :maxlength="200"/></Field><Field><FieldLabel>共享范围</FieldLabel><OptionPicker v-model="draft.visibility" aria-label="测试集共享范围" class="min-w-36" :options="visibilityOptions"/><template #help><HelpTip text="团队测试集仅能引用团队可用的用例，其他成员可执行，原作者和管理员可编辑。"/></template></Field></div></fieldset><div class="filters"><OptionPicker v-if="draft.can_edit" v-model="toAdd" :disabled="saving||draft.case_ids.length>=20" placeholder="选择要加入的用例" aria-label="添加测试集用例" style="width:min(420px,100%)" @change="add" :options="available"/><Badge variant="secondary">{{draft.case_ids.length}} 个用例 · {{plan.units}} 个数据组合 · {{plan.steps}} 步</Badge><HelpTip text="按列表顺序执行，可调整先后。执行前核对实际用例版本；超出 20 个组合或 100 步时请拆成多个测试集。测试集不会额外复制请求或连接配置。"/></div><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:720}).y?({x:720}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:720}).x||({x:720}).minWidth||740)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(70)+'px'}">顺序</TableHead><TableHead>用例</TableHead><TableHead :style="{width:(150)+'px'}">模块</TableHead><TableHead :style="{width:(150)+'px'}">版本 / 数据组</TableHead><TableHead v-if="draft.can_edit" :style="{width:(220)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (selected||[])" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{rowIndex} in [{record,rowIndex}]">{{rowIndex+1}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><span :class="{missing:record.missing}">TC-{{record.id}} · {{record.name||'已删除或无权访问，请移除'}}</span></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["module"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">v{{record.revision||'—'}} · {{Math.max(1,record.data_rows?.length||0)}} 组</template></div></TableCell><TableCell v-if="draft.can_edit" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{rowIndex} in [{record,rowIndex}]"><Button @click="move(rowIndex,-1)" variant="ghost" size="sm" type="button" :disabled="(rowIndex===0||saving)">上移</Button><Button @click="move(rowIndex,1)" variant="ghost" size="sm" type="button" :disabled="(rowIndex===selected.length-1||saving)">下移</Button><Button @click="draft.case_ids.splice(rowIndex,1)" variant="ghost" size="sm" type="button" :disabled="(saving)">移除</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(selected||[]).length"><TableCell :colspan="5"><Empty><EmptyHeader><EmptyDescription>{{"从上方选择已有用例加入测试集"}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><Accordion class="suite-bindings" type="multiple" :model-value="(bindingsOpen||[]).map(String)" @update:model-value="bindingsOpen=$event;"><AccordionItem item-key="bindings" :value="String('panel')"><AccordionTrigger>详细设置</AccordionTrigger><AccordionContent force-mount v-show="!(!(bindingsOpen||[]).map(String).includes(String('panel')))"><SuiteBindings :bindings="draft.bindings" :cases="plan.selected" :disabled="saving||!draft.can_edit"/></AccordionContent></AccordionItem></Accordion></template></PageSurface></main></template>
<style scoped>.suite-bindings{margin-top:20px}.suites-page{height:100dvh;min-width:0;width:100%;overflow:auto;box-sizing:border-box;background:var(--bg);color:var(--text)}.filters{display:flex;gap:12px;align-items:center;margin-bottom:20px;flex-wrap:wrap}.basic{display:grid;grid-template-columns:2fr 1fr;gap:20px}.suite-name{max-width:100%;white-space:normal;text-align:left;justify-content:flex-start}.missing{color:var(--destructive)}@media(max-width:800px){.basic{grid-template-columns:1fr}.suite-bindings{margin-top:20px}}</style>
